--[[ WDYM HUB · PROTECTED SCRIPT ]]--
local _b64 = ""

local function _decode(s)
    local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local t = {}
    for i = 1, #b do t[b:sub(i,i)] = i - 1 end
    local res = {}
    local idx = 1
    s = s:gsub("[^A-Za-z0-9%+/=]", "")
    for i = 1, #s, 4 do
        local c1 = t[s:sub(i,   i  )] or 0
        local c2 = t[s:sub(i+1, i+1)] or 0
        local c3 = t[s:sub(i+2, i+2)] or 0
        local c4 = t[s:sub(i+3, i+3)] or 0
        -- Pure math decode (no bitwise ops needed — universal Lua 5.1+ compatible)
        local n = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
        res[idx] = string.char(math.floor(n / 65536)); idx = idx + 1
        if s:sub(i+2, i+2) ~= "=" then
            res[idx] = string.char(math.floor(n / 256) % 256); idx = idx + 1
        end
        if s:sub(i+3, i+3) ~= "=" then
            res[idx] = string.char(n % 256); idx = idx + 1
        end
    end
    return table.concat(res)
end

local _src = _decode(_b64)
local _fn, _err = (loadstring or load)(_src)
if _fn then
    local _ok, _execErr = pcall(_fn)
    if not _ok then
        warn("[WDYM] Runtime Error: " .. tostring(_execErr))
    end
else
    warn("[WDYM] Load Error: " .. tostring(_err))
end
